from app.main import app
from tests.libs.client_portal.conftest import make_client, make_model, make_model_material, make_subscription

_NOT_FOUND_MSG = "No material uploaded for this model"


class _SpyStorage:
    """FileStorage double whose .open() records every call -- proves a
    rejected request never reaches the filesystem (§8.3 invariant)."""

    def __init__(self) -> None:
        self.open_calls: list[str] = []

    def open(self, storage_key: str):
        self.open_calls.append(storage_key)
        return io.BytesIO(b"material bytes")


@pytest.fixture
def spy_storage(monkeypatch):
    storage = _SpyStorage()
    monkeypatch.setattr("app.libs.client_portal.service.get_storage", lambda bucket: storage)
    return storage


# --- Positive: a subscribed client's download is unchanged ------------------------


def test_subscribed_client_receives_the_stream_unchanged(session, spy_storage):
    client_user = make_client(session, name="Cathy Client")
    model = make_model(session, name="Alpha Model")
    make_subscription(session, client_user, model)
    material = make_model_material(session, model, storage_key="marketing/alpha-v0.pdf")

    svc = ClientPortalService(session)
    stream, filename, content_type = svc.model_material_stream(model.id, user_id=client_user.id)

    assert filename == material.filename
    assert content_type == material.content_type
    assert stream.read() == b"material bytes"
    assert spy_storage.open_calls == ["marketing/alpha-v0.pdf"]


# --- Negative: unsubscribed client gets the SAME 404 as an unknown model ----------


def test_unsubscribed_client_gets_404_identical_to_unknown_model(session, spy_storage):
    client_user = make_client(session, name="Cathy Client")
    model = make_model(session, name="Alpha Model")
    make_model_material(session, model, storage_key="marketing/alpha-v0.pdf")  # material EXISTS

    svc = ClientPortalService(session)

    with pytest.raises(HTTPException) as unsubscribed_exc:
        svc.model_material_stream(model.id, user_id=client_user.id)

    with pytest.raises(HTTPException) as unknown_model_exc:
        svc.model_material_stream(uuid.uuid4(), user_id=client_user.id)

    assert unsubscribed_exc.value.status_code == 404
    assert unknown_model_exc.value.status_code == 404
    # Byte-identical bodies -- a future divergence that leaks model existence
    # to an unentitled caller must fail this assertion.
    assert unsubscribed_exc.value.detail == unknown_model_exc.value.detail == _NOT_FOUND_MSG
    assert spy_storage.open_calls == []


def test_client_subscribed_to_a_different_model_is_also_rejected(session, spy_storage):
    client_user = make_client(session, name="Cathy Client")
    subscribed_model = make_model(session, name="Subscribed Model")
    other_model = make_model(session, name="Other Model")
    make_subscription(session, client_user, subscribed_model)
    make_model_material(session, other_model, storage_key="marketing/other-v0.pdf")

    svc = ClientPortalService(session)
    with pytest.raises(HTTPException) as exc_info:
        svc.model_material_stream(other_model.id, user_id=client_user.id)

    assert exc_info.value.status_code == 404
    assert exc_info.value.detail == _NOT_FOUND_MSG
    assert spy_storage.open_calls == []


@pytest.mark.parametrize(
    "seed_material",
    [True, False],
    ids=["material-exists-but-unentitled", "material-does-not-exist"],
)
def test_no_403_is_ever_emitted_on_rejection(session, spy_storage, seed_material):
    client_user = make_client(session, name="Cathy Client")
    model = make_model(session, name="Alpha Model")
    if seed_material:
        make_model_material(session, model, storage_key="marketing/alpha-v0.pdf")

    svc = ClientPortalService(session)
    with pytest.raises(HTTPException) as exc_info:
        svc.model_material_stream(model.id, user_id=client_user.id)

    assert exc_info.value.status_code != 403
    assert exc_info.value.status_code == 404


