def test_fully_redeemed_client_loses_material_access(session, spy_storage):
    """A full redemption floors client_subscriptions.multiplier at 0 rather
    than deleting the row (permanent client_ib_accounts anchor) -- entitlement
    must not survive that as a plain row-existence check would let it."""
    client_user = make_client(session, name="Cathy Client")
    model = make_model(session, name="Alpha Model")
    make_subscription(session, client_user, model, multiplier=Decimal("0"))
    make_model_material(session, model, storage_key="marketing/alpha-v0.pdf")

    svc = ClientPortalService(session)
    with pytest.raises(HTTPException) as exc_info:
        svc.model_material_stream(model.id, user_id=client_user.id)

    assert exc_info.value.status_code == 404
    assert exc_info.value.detail == _NOT_FOUND_MSG
    assert spy_storage.open_calls == []


def test_the_subscription_lookup_uses_user_id_model_id_order(session):
    """has_subscription(user_id, model_id) -- proves the two positional
    arguments are not silently swappable (the PK order the impl doc pins)."""
    client_user = make_client(session, name="Cathy Client")
    model = make_model(session, name="Alpha Model")
    make_subscription(session, client_user, model)

    repo = ClientPortalRepository(session)
    assert repo.has_subscription(client_user.id, model.id) is True
    # Swapped args -- two random-looking UUIDs that don't collide with any
    # real row -- must not accidentally match.
    assert repo.has_subscription(model.id, client_user.id) is False  # type: ignore[arg-type]


# --- Router: dependency wiring passes the real caller's id, not a stub -----------


@pytest.fixture
def client(session, db_factory):
    def _override_get_db():
        db = db_factory()
        try:
            yield db
        finally:
            db.close()

    def _make(stub_user):
        app.dependency_overrides[get_db] = _override_get_db
        app.dependency_overrides[get_current_client_user] = lambda: stub_user
        return TestClient(app)

    yield _make
    app.dependency_overrides.clear()


def test_router_download_succeeds_for_a_subscribed_client(session, db_factory, client, spy_storage):
    db = db_factory()
    client_user = make_client(db, name="Cathy Client")
    model = make_model(db, name="Alpha Model")
    make_subscription(db, client_user, model)
    make_model_material(db, model, storage_key="marketing/alpha-v0.pdf")

    http = client(client_user)
    resp = http.get(f"/client/models/{model.id}/material")

    assert resp.status_code == 200
    assert resp.content == b"material bytes"


def test_router_download_404s_identically_for_an_unsubscribed_client(
    session, db_factory, client, spy_storage
):
    db = db_factory()
    client_user = make_client(db, name="Cathy Client")
    model = make_model(db, name="Alpha Model")
    make_model_material(db, model, storage_key="marketing/alpha-v0.pdf")

    http = client(client_user)

    unsubscribed_resp = http.get(f"/client/models/{model.id}/material")
    unknown_model_resp = http.get(f"/client/models/{uuid.uuid4()}/material")

    assert unsubscribed_resp.status_code == 404
    assert unknown_model_resp.status_code == 404
    assert unsubscribed_resp.status_code != 403
    assert unsubscribed_resp.json() == unknown_model_resp.json()
    assert spy_storage.open_calls == []


